<script setup lang="ts">
import {ref,onMounted,watch,onUnmounted,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Modal from '../../../components/Modal.vue'
import {session,notify} from '../../../api'
import VehicleForm from '../components/VehicleForm.vue'
import {vehicleFacade} from '../facade/vehicleFacade'
import type {Vehicle,VehiclePage} from '../types/vehicle'
import {customerFacade} from '../../customers/facade/customerFacade'
import type {WorkshopOption} from '../../customers/types/customer'
import {statusApi} from '../../statuses/api/statusApi'
import StatusSelector from '../../statuses/components/StatusSelector.vue'
import {statusLabel,type EntityStatus} from '../../statuses/types/status'
import {displayText} from '../../shared/presentation'
const route=useRoute(),router=useRouter(),workshops=ref<WorkshopOption[]>([]),workshop=ref<number|''>(''),page=ref(1),query=ref(''),direction=ref('ASC'),statusFilter=ref<number|''>(''),statuses=ref<EntityStatus[]>([]),result=ref<VehiclePage>({items:[],page:1,pageSize:10,totalItems:0,totalPages:0}),selected=ref<Vehicle|null>(null),editing=ref(false),creating=ref(false),loading=ref(false),busy=ref(false),error=ref('')
let generation=0,timer:ReturnType<typeof setTimeout>|undefined
const pages=computed(()=>{const start=Math.max(1,Math.min(page.value-2,result.value.totalPages-4));return Array.from({length:Math.min(5,result.value.totalPages)},(_,i)=>start+i)})
async function load(){if(!workshop.value)return;const n=++generation;loading.value=true;error.value='';try{const data=await vehicleFacade.list(Number(workshop.value),page.value,direction.value,query.value,statusFilter.value||undefined);if(n===generation)result.value=data}catch(e){if(n===generation)error.value=(e as Error).message}finally{if(n===generation)loading.value=false}}
async function select(id:number){if(busy.value)return;busy.value=true;error.value='';try{selected.value=await vehicleFacade.get(id,Number(workshop.value))}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function saved(){editing.value=false;creating.value=false;await load();if(selected.value)await select(selected.value.id)}
async function status(id:number){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{selected.value=await vehicleFacade.status(selected.value.id,Number(workshop.value),selected.value.version,id);notify('Estatus actualizado');await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
watch(workshop,()=>{selected.value=null;page.value=1;void router.replace({path:'/vehicles',query:{workshopId:workshop.value}});void load()});watch([page,direction],()=>void load());watch(statusFilter,()=>{if(page.value!==1)page.value=1;else void load()});watch(query,()=>{clearTimeout(timer);timer=setTimeout(()=>{if(page.value!==1)page.value=1;else void load()},300)})
onMounted(async()=>{try{[workshops.value,statuses.value]=await Promise.all([customerFacade.workshopsList(),statusApi.list('vehicles')]);workshop.value=workshops.value.find(w=>w.id===Number(route.query.workshopId))?.id??workshops.value[0]?.id??''}catch(e){error.value=(e as Error).message}});onUnmounted(()=>{generation++;clearTimeout(timer)})
</script>
<template><section class="page"><div class="page-heading"><div><h1>Vehículos</h1><p class="muted">Directorio por taller. En servicio se calcula a partir de las órdenes abiertas.</p></div><button v-if="['ADMIN','RECEPTIONIST'].includes(session.user?.role)" class="btn primary" :disabled="!workshop||busy" @click="creating=true">Registrar vehículo</button></div><p v-if="error" class="error" role="alert">{{error}} <button @click="load">Reintentar</button></p><section class="panel"><div class="table-toolbar"><label>Taller<select v-model="workshop" :disabled="busy||editing||creating"><option value="" disabled>Selecciona un taller</option><option v-for="w in workshops" :key="w.id" :value="w.id">{{displayText(w.name)}}</option></select></label><label>Buscar<input v-model="query" maxlength="160" placeholder="VIN, placa, marca o modelo"></label><label>Estatus<select v-model="statusFilter"><option value="">Todos</option><option v-for="s in statuses" :key="s.id" :value="s.id">{{statusLabel(s)}}</option></select></label><label>Orden por marca<select v-model="direction"><option value="ASC">A → Z</option><option value="DESC">Z → A</option></select></label><span>{{result.totalItems}} vehículos</span></div><p v-if="loading" role="status">Cargando vehículos…</p><div v-else class="table-wrap"><table><thead><tr><th>Vehículo</th><th>VIN / placa</th><th>Propietario</th><th>Estatus</th><th>Ficha</th></tr></thead><tbody><tr v-for="v in result.items" :key="v.id"><td>{{displayText(v.make)}} {{displayText(v.model)}} · {{v.year||'Año no registrado'}}</td><td>{{v.vin||'VIN no registrado'}}<small>{{v.plate||'Placa no registrada'}}</small></td><td>{{displayText(v.customerName)}}</td><td>{{statusLabel({code:v.statusCode})}}{{v.inService?' · En servicio':''}}</td><td><button class="text-link" :disabled="busy" @click="select(v.id)">Ver ficha</button></td></tr></tbody></table><p v-if="!result.items.length" class="empty">Sin vehículos para esta consulta.</p></div><nav v-if="result.totalPages" class="pagination" aria-label="Páginas de vehículos"><button :disabled="loading||page===1" @click="page--">Anterior</button><button v-for="p in pages" :key="p" :disabled="loading||p===page" :aria-current="p===page?'page':undefined" @click="page=p">{{p}}</button><button :disabled="loading||page>=result.totalPages" @click="page++">Siguiente</button><span>Página {{result.page}} de {{result.totalPages}} · Hasta 10 por página</span></nav></section><section v-if="selected" class="customer-detail"><header class="customer-detail-header"><h2>{{displayText(selected.make)}} {{displayText(selected.model)}} · {{selected.plate||'Sin placa'}}</h2><div class="button-row"><button class="btn secondary" :disabled="busy" @click="editing=true">Editar vehículo</button><button class="btn secondary" :disabled="busy" @click="selected=null">Cerrar ficha</button></div></header><div class="info-section"><p>VIN: {{selected.vin||'No registrado'}} · Año: {{selected.year||'No registrado'}}</p><p>Versión: {{displayText(selected.trim)||'No registrada'}} · Color: {{displayText(selected.color)||'No registrado'}} · Kilometraje: {{selected.odometer??'No registrado'}}</p><p>Propietario: {{displayText(selected.customerName)}}</p><p>{{selected.statusDescription}}{{selected.inService?' · En servicio':''}}</p><StatusSelector :statuses="statuses" :status-id="selected.statusId" :busy="busy" @change="status"/></div></section><Modal v-if="creating||editing&&selected" :title="creating?'Registrar vehículo':'Editar vehículo'" :busy="busy" embedded-form @close="creating=false;editing=false"><VehicleForm :workshop-id="Number(workshop)" :initial="creating?undefined:selected!" @saved="saved" @busy="busy=$event" @cancel="creating=false;editing=false"/></Modal></section></template>
